import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"AppHeader（顶栏积木）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/app-layout/docs/README-AppHeader.md","filePath":"docs/core/src/components/app-layout/docs/README-AppHeader.md"}'),s={name:"docs/core/src/components/app-layout/docs/README-AppHeader.md"};function i(r,e,l,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="appheader-顶栏积木" tabindex="-1">AppHeader（顶栏积木） <a class="header-anchor" href="#appheader-顶栏积木" aria-label="Permalink to &quot;AppHeader（顶栏积木）&quot;">​</a></h1><blockquote><p>顶栏布局积木：#left 品牌/业务入口 + 路由大模块菜单 + #right 操作区（userEntry/settings/themeSwitcher 落位）。 范式页：<code>apps/reference/src/pages/app-layout/shell/</code>（自供 shell 积木直引）、<code>apps/reference/src/pages/app-layout/layout/</code>（NoHeader 显隐变体）</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：内置 AppShell 经典布局已直引；自供 shell 时按需复用</li><li>#left = 品牌/业务入口（AppLayout <code>#brand</code> 锚落位）；#right = userEntry/settings/themeSwitcher 操作区</li><li>中间区 = 路由大模块菜单（menus 渲染，点击高亮 activeModulePath）</li><li>整体显隐由 AppLayout 间接控制（store headerStyle.height=0 视觉收起 + dom 保留）</li><li><strong>面貌（背景 / 圆角 / 横向内呼吸）三项同源</strong> —— 都在 <code>appStore.headerStyle</code> 这一份 inline style 里 （[MUST NOT] 把其中任何一项挪回 scoped CSS：一半 inline 一半 CSS 会让消费方覆盖时只改得动一半）</li></ul><h2 id="模块条徽标-badge" tabindex="-1">模块条徽标（badge） <a class="header-anchor" href="#模块条徽标-badge" aria-label="Permalink to &quot;模块条徽标（badge）&quot;">​</a></h2><p>模块条的每一项以其路由 <strong><code>path</code> 为 key</strong> 查 <code>bridge.badge</code> 注册表，命中则渲染绝对定位角标（数量 / 新 / 更新 / 内测 / 开发中 / 自定义），<strong>不压字、不改变宿主尺寸</strong>；未命中零影响、无需在菜单数据里加字段。</p><p>与 AppSidebar 菜单树同一份注册表、同一套 key 规则——同一个 <code>path</code> 在两处显示同一个标。</p><p><strong>挂标项留位</strong>（ii3dzw）：角标不占位、向右逃逸，而模块条各项首尾相接 ⇒ 挂标项按实测逃逸量（角标右缘 − 被包内容右缘） 补同宽右内边距，角标不再压右邻项；无标项与此前逐字一致。实现收在同级 <code>use-header-module-badge-room.ts</code> （MutationObserver 追角标出现 / 文案 / 隐藏态；量值与项 padding 无关，无自反馈）。</p><p><strong>新标签页打开</strong>：模块项路由 <code>meta.menu.target: &quot;_blank&quot;</code> ⇒ 点击新标签页打开，不 <code>router.push</code>、激活模块不变（同 <code>MenuTree</code>，见 menu 族 README）。</p><blockquote><p>AppHeader 的模块条是<strong>自建实现</strong>（扁平一级 + 横向滚动 + <code>router.push</code> 切模块），不走 <code>MenuTree</code>；徽标是两处各自接入的，行为对齐。契约见 <a href="/done-coding-showcase/docs/core/src/bridge/docs/README.html">bridge 文档 · 徽标注册表</a>。</p></blockquote><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>经 AppLayout 内容锚填充后由 shell 落位（App.vue 范式——#brand/#userEntry 即 Header #left/#right 的内容来源）：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AppLayout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bridge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appCoreBridge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">appStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appStore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">userStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">userStore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;template #brand&gt;&lt;AppBrand /&gt;&lt;/template&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;template #userEntry&gt;&lt;UserHeaderAction /&gt;&lt;/template&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AppLayout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li>自供 shell 直引积木时，把 AppLayout 内容锚转发到对应槽（见 AppSidebar 文档的 DemoCustomShell 槽转发范式）</li><li><code>menus</code> 渲染路由大模块（带 menuIcon 时图标 + 标题）；<code>menuFlatList</code> 扁平菜单（必填）供内部匹配</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong><code>show</code> 勿用于显隐</strong>：声明必填但模板未消费（仅预留未来定位子元素 v-if 接口）——整体显隐由 AppLayout 经 store 间接控制（<code>headerStyle.height=0</code> 视觉收起 + dom 保留），默认即够用，[MUST NOT] 自行传值。</li><li><strong>中间区模块菜单按需</strong>：<code>menus</code> / <code>activeMenu</code> / <code>activeModuleMenu</code> 仅当需要「路由大模块菜单」时才填（默认空数组即无中间菜单区）；<code>menuFlatList</code> 必填（内部匹配）。</li><li><code>#left</code> / <code>#right</code> 槽内容来自 AppLayout 内容锚转发（<code>#brand</code> → <code>#left</code>；<code>#userEntry</code> / <code>#settings</code> / <code>#themeSwitcher</code> → <code>#right</code>）——内置 shell 零配置；自供 shell 直引时按槽转发范式接住。</li><li><strong>完整能力演示</strong>（自供 shell 积木直引 + NoHeader 变体）：<code>apps/reference/src/pages/app-layout/shell/</code>、<code>apps/reference/src/pages/app-layout/layout/</code></li></ul><h2 id="面貌与覆盖-背景-圆角-内呼吸" tabindex="-1">面貌与覆盖（背景 / 圆角 / 内呼吸） <a class="header-anchor" href="#面貌与覆盖-背景-圆角-内呼吸" aria-label="Permalink to &quot;面貌与覆盖（背景 / 圆角 / 内呼吸）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>覆盖法</th></tr></thead><tbody><tr><td>背景</td><td><code>APP_LAYOUT_HEADER_CONFIG.background ?? 主题 bodyColor</code></td><td>配 <code>background</code>（支持色 / 渐变 / 背景图）</td></tr><tr><td>圆角</td><td><code>var(--dc-core-radius, var(--el-border-radius-base))</code>（随主题）</td><td><code>APP_LAYOUT_HEADER_CONFIG.style.borderRadius</code></td></tr><tr><td>横向内呼吸</td><td>间距阶梯<strong>模块档</strong>（<code>gap.size</code> × 密度 × 1，默认 <strong>8px</strong>）</td><td><code>APP_LAYOUT_HEADER_CONFIG.style.padding</code></td></tr></tbody></table><ul><li>圆角 / padding 的默认值<strong>在 <code>...cfg.style</code> 展开之前</strong>写入 ⇒ <code>style</code> 逃生舱里的同名键恒赢，可整体覆盖。 （<code>position</code> / <code>top</code> / <code>left</code> / <code>right</code> / <code>height</code> / <code>background</code> / <code>color</code> 是<strong>引擎托管键</strong>，写在展开之后， 外部传了也压不过——这条不变。）</li><li><code>box-sizing: border-box</code> 由引擎托管：横向 padding 恒收在盒内，[MUST NOT] 指望消费方的全局 reset。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>show</code></td><td><code>boolean</code>（必填）</td><td>—</td><td>⚠️ 模板内实际未消费（仅预留未来定位子元素 v-if 接口，源码注释口径）</td></tr><tr><td><code>menus</code></td><td><code>RouteMetaResolveRaw[]</code></td><td><code>() =&gt; []</code></td><td>模块菜单</td></tr><tr><td><code>activeMenu?</code></td><td><code>RouteMetaResolveRaw</code></td><td>无</td><td>聚焦的路由菜单</td></tr><tr><td><code>activeModuleMenu?</code></td><td><code>RouteMetaResolveRaw</code></td><td>无</td><td>聚焦的模块菜单</td></tr><tr><td><code>menuFlatList</code></td><td><code>RouteMetaResolveRaw[]</code>（必填）</td><td>—</td><td>扁平菜单</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#left</code></td><td>无</td><td>品牌/业务入口（AppLayout #brand 落位）</td></tr><tr><td><code>#right</code></td><td>无</td><td>userEntry/settings/themeSwitcher 操作区</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong><code>show</code> 勿用于显隐控制</strong>：声明必填但模板未消费——整体显隐由 AppLayout 经 store 间接控制（headerStyle.height=0 视觉收起 + dom 保留）</li><li>主题切换器不属 Header 私有：已解耦为 <code>AppTheme</code>，经 shell #right 注入（默认内容仍是 AppTheme，经典布局 1:1 镜像）</li><li><strong>[MUST NOT] 在 scoped CSS 里给 <code>.app-header-shim</code> 写死横向 padding</strong>：那会与 inline 的一份打架，且消费方覆盖只改得动一半——横向内呼吸的唯一出处是 <code>headerStyle</code></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>内容锚：<code>#brand</code> → <code>#left</code>；<code>#userEntry</code> / <code>#settings</code> / <code>#themeSwitcher</code> → <code>#right</code>（落位见 AppLayout 文档）</li><li>主题切换：<code>AppTheme</code>（themeSwitcher 默认内容）</li><li>范式页：<code>apps/reference/src/pages/app-layout/shell/</code>、<code>apps/reference/src/pages/app-layout/layout/</code></li></ul>`,34)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
